#### 5.6.6 Authentication and Session Management

Micro-frontends must implement secure authentication and session management:

**OAuth 2.0 / OpenID Connect Integration**:

```javascript
// Authentication service using OAuth2 Authorization Code Flow + PKCE
import { AuthorizationServiceConfiguration, AuthorizationRequest } from '@openid/appauth';

class AuthenticationService {
  private authConfig: AuthorizationServiceConfiguration;

  async init() {
    this.authConfig = await AuthorizationServiceConfiguration.fetchFromIssuer(
      'https://auth.gainwell.com'
    );
  }

  async login(): Promise<void> {
    // Generate PKCE code verifier and challenge
    const codeVerifier = this.generateCodeVerifier();
    const codeChallenge = await this.generateCodeChallenge(codeVerifier);

    const request = new AuthorizationRequest({
      client_id: 'claims-mfe-client',
      redirect_uri: 'https://medicaid.gainwell.com/auth/callback',
      scope: 'openid profile email claims.read claims.write',
      response_type: 'code',
      state: this.generateState(),
      code_challenge: codeChallenge,
      code_challenge_method: 'S256',
    });

    // Store code verifier for token exchange
    sessionStorage.setItem('pkce_code_verifier', codeVerifier);

    // Redirect to authorization server
    window.location.href = this.authConfig.authorizationEndpoint + '?' + request.toQueryString();
  }

  async handleCallback(): Promise<void> {
    const urlParams = new URLSearchParams(window.location.search);
    const code = urlParams.get('code');
    const state = urlParams.get('state');

    // Verify state parameter to prevent CSRF
    if (state !== sessionStorage.getItem('oauth_state')) {
      throw new Error('Invalid state parameter - possible CSRF attack');
    }

    // Exchange authorization code for tokens
    const codeVerifier = sessionStorage.getItem('pkce_code_verifier');
    const tokenResponse = await fetch(this.authConfig.tokenEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        code: code,
        redirect_uri: 'https://medicaid.gainwell.com/auth/callback',
        client_id: 'claims-mfe-client',
        code_verifier: codeVerifier,
      }),
    });

    const tokens = await tokenResponse.json();
    this.storeTokensSecurely(tokens);
  }

  private storeTokensSecurely(tokens: any): void {
    // Store access token in httpOnly secure cookie (via backend API)
    // Store refresh token in httpOnly secure cookie (via backend API)
    // Never store tokens in localStorage - vulnerable to XSS

    fetch('https://api.gainwell.com/v1/auth/session', {
      method: 'POST',
      credentials: 'include',  // Send cookies
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        access_token: tokens.access_token,
        refresh_token: tokens.refresh_token,
        id_token: tokens.id_token,
      }),
    });
  }
}
```

**Secure Session Cookies**:

Backend API sets httpOnly secure cookies for session management:

```javascript
// Backend API (Node.js/Express) - sets session cookie
app.post('/v1/auth/session', (req, res) => {
  const { access_token, refresh_token, id_token } = req.body;

  // Validate tokens (verify JWT signatures)
  const decodedToken = verifyJWT(id_token);

  // Create session
  const sessionId = uuidv4();
  redisClient.setex(`session:${sessionId}`, 3600, JSON.stringify({
    userId: decodedToken.sub,
    access_token,
    refresh_token,
  }));

  // Set httpOnly secure cookie
  res.cookie('session_id', sessionId, {
    httpOnly: true,      // Prevent JavaScript access
    secure: true,        // HTTPS only
    sameSite: 'strict',  // CSRF protection
    maxAge: 3600000,     // 1 hour
    path: '/',
    domain: '.gainwell.com',
  });

  res.json({ success: true });
});
```

**CSRF Protection**:

```javascript
// Frontend: Include CSRF token in API requests
const apiClient = axios.create({
  baseURL: 'https://api.gainwell.com',
  withCredentials: true,  // Send cookies
});

// Add CSRF token interceptor
apiClient.interceptors.request.use(async (config) => {
  // Retrieve CSRF token from meta tag (set by backend)
  const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content');
  if (csrfToken) {
    config.headers['X-CSRF-Token'] = csrfToken;
  }
  return config;
});

// Usage
await apiClient.post('/v1/claims', claimData);
```

**Token Refresh Mechanism**:

```javascript
// Automatic token refresh before expiration
class TokenRefreshService {
  private refreshTimer: NodeJS.Timeout | null = null;

  startAutoRefresh(): void {
    // Refresh token 5 minutes before expiration
    const refreshInterval = 55 * 60 * 1000; // 55 minutes

    this.refreshTimer = setInterval(async () => {
      await this.refreshAccessToken();
    }, refreshInterval);
  }

  async refreshAccessToken(): Promise<void> {
    try {
      const response = await fetch('https://api.gainwell.com/v1/auth/refresh', {
        method: 'POST',
        credentials: 'include',  // Send refresh token cookie
      });

      if (response.ok) {
        console.log('Access token refreshed successfully');
      } else {
        // Refresh failed - redirect to login
        this.handleRefreshFailure();
      }
    } catch (error) {
      console.error('Token refresh failed:', error);
      this.handleRefreshFailure();
    }
  }

  private handleRefreshFailure(): void {
    this.stopAutoRefresh();
    window.location.href = '/login?reason=session_expired';
  }

  stopAutoRefresh(): void {
    if (this.refreshTimer) {
      clearInterval(this.refreshTimer);
    }
  }
}
```

**Key Authentication Security Controls**:

- **OAuth2 + PKCE**: Use Authorization Code Flow with Proof Key for Code Exchange
- **httpOnly Secure Cookies**: Store session tokens in httpOnly cookies (not localStorage)
- **CSRF Protection**: Include CSRF tokens in state-changing requests
- **Token Expiration**: Access tokens expire in 60 minutes; refresh tokens expire in 8 hours
- **Automatic Logout**: Clear session after 15 minutes of inactivity (HIPAA requirement)
- **Multi-Factor Authentication**: Require MFA for access to PHI-containing applications
